// news-image-20261123: the front page for Monday 23 November 2026.
// Lead story: Ukraine sinks the Russian corvette Merkury off Libya;
// seven more stories inside. Rendered by draw.py (Pillow).
//
// The image itself is embedded below as a single base64 line (see
// pack.mjs, which fills in PAYLOAD from entry.png). This program only
// decodes that payload and writes it out, so every run produces the
// same bytes. No network, no randomness, no other input.
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const PAYLOAD = "";

if (!PAYLOAD) {
  throw new Error("entry image payload is empty; run node pack.mjs first");
}

const outDir = process.env.MAKEFUN_OUTPUT_DIR || "/output";
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, "entry.png"), Buffer.from(PAYLOAD, "base64"));
console.log("wrote " + join(outDir, "entry.png"));
